    public interface StreamBuilders {
        /**
         * Stream (camel-stream)
         * Read from System.in, a file or an HTTP URL, and write to System.out,
         * System.err, a file or an output stream in a message header.
         * 
         * Category: file,core
         * Since: 1.3
         * Maven coordinates: org.apache.camel:camel-stream
         * 
         * @return the dsl builder for the headers' name.
         */
        default StreamHeaderNameBuilder stream() {
            return StreamHeaderNameBuilder.INSTANCE;
        }
        /**
         * Stream (camel-stream)
         * Read from System.in, a file or an HTTP URL, and write to System.out,
         * System.err, a file or an output stream in a message header.
         * 
         * Category: file,core
         * Since: 1.3
         * Maven coordinates: org.apache.camel:camel-stream
         * 
         * Syntax: <code>stream:kind</code>
         * 
         * Path parameter: kind (required)
         * The kind of stream. The consumer reads from in (System.in), file (the
         * file of fileName) or http (the URL of httpUrl). The producer writes
         * to out (System.out), err (System.err), file (the file of fileName) or
         * header (the java.io.OutputStream in the stream header of the
         * message). Any other kind fails when the consumer or producer is
         * created.
         * There are 6 enums and the value can be one of: in, out, err, header,
         * file, http
         * 
         * @param path kind
         * @return the dsl builder
         */
        default StreamEndpointBuilder stream(String path) {
            return StreamEndpointBuilderFactory.endpointBuilder("stream", path);
        }
        /**
         * Stream (camel-stream)
         * Read from System.in, a file or an HTTP URL, and write to System.out,
         * System.err, a file or an output stream in a message header.
         * 
         * Category: file,core
         * Since: 1.3
         * Maven coordinates: org.apache.camel:camel-stream
         * 
         * Syntax: <code>stream:kind</code>
         * 
         * Path parameter: kind (required)
         * The kind of stream. The consumer reads from in (System.in), file (the
         * file of fileName) or http (the URL of httpUrl). The producer writes
         * to out (System.out), err (System.err), file (the file of fileName) or
         * header (the java.io.OutputStream in the stream header of the
         * message). Any other kind fails when the consumer or producer is
         * created.
         * There are 6 enums and the value can be one of: in, out, err, header,
         * file, http
         * 
         * @param componentName to use a custom component name for the endpoint
         * instead of the default name
         * @param path kind
         * @return the dsl builder
         */
        default StreamEndpointBuilder stream(String componentName, String path) {
            return StreamEndpointBuilderFactory.endpointBuilder(componentName, path);
        }

    }
    /**
     * The builder of headers' name for the Stream component.
     */
    public static class StreamHeaderNameBuilder {
        /**
         * The internal instance of the builder used to access to all the
         * methods representing the name of headers.
         */
        public static final StreamHeaderNameBuilder INSTANCE = new StreamHeaderNameBuilder();

        /**
         * The index of the exchange in the stream, starting at 0 and counting
         * each exchange that the consumer creates: a line, a group of lines, or
         * the bytes of one read. With scanStream and retry, the count goes on
         * after the stream is opened again.
         * 
         * The option is a: {@code long} type.
         * 
         * Group: consumer
         * 
         * @return the name of the header {@code StreamIndex}.
         */
        public String streamIndex() {
            return "CamelStreamIndex";
        }
        /**
         * Whether the exchange is the last one of the stream. The consumer
         * reads one line ahead to know it, except for kind in, where it is true
         * for each line. Always false with scanStream, as a scanned stream
         * never ends.
         * 
         * The option is a: {@code boolean} type.
         * 
         * Group: consumer
         * 
         * @return the name of the header {@code StreamComplete}.
         */
        public String streamComplete() {
            return "CamelStreamComplete";
        }
    }
    static StreamEndpointBuilder endpointBuilder(String componentName, String path) {
        class StreamEndpointBuilderImpl extends AbstractEndpointBuilder implements StreamEndpointBuilder, AdvancedStreamEndpointBuilder {
            public StreamEndpointBuilderImpl(String path) {
                super(componentName, path);
            }
        }
        return new StreamEndpointBuilderImpl(path);
    }
